#pragma once
#include <array>
#include <string_view>
#include <vector>
namespace bo3z::codex
{
	struct Chapter { int book; std::string_view title, image; std::vector<std::string_view> paras; };
	inline constexpr std::array<std::string_view, 15> kBooks{ "The Curse of Alduin", "The Summoner's Path", "The Battle-mage's Path", "The Ranger's Path", "The Spellsword's Path", "The Broken Words: Riverwood", "The Broken Words: Whiterun", "The Broken Words: Solitude", "The Broken Words: Windhelm", "The Broken Words: Markarth", "The Broken Words: Riften", "The Broken Words: Falkreath", "The Broken Words: Morthal", "The Broken Words: Dawnstar", "The Broken Words: Winterhold" };  // 0 the lore, 1-4 the class guides (Summoner, Destruction, Ranger, Spellsword), 5+ a freed city's page (kTowns order)
	inline const std::vector<Chapter> kChapters{
		{ 0, "The Greybeard's Account", "sigil", { "Written at High Hrothgar by a Greybeard who broke his silence, for whoever lived through Helgen" } },
		{ 0, "I. What Happened", "helgen", { "When Alduin rose over Helgen, he shouted three Words into the earth: <b>SLEN TIID VO</b> - Flesh, Time, Undo. It is the shout that raises the dead.", "His mist also covers the door of <b>Sovngarde</b>, so the dead of Skyrim cannot pass on. They lie restless in the ground. By day they sleep. When the sun goes down, they rise." } },
		{ 0, "II. The Dead", "graves", { "Each night the dead come in <b>waves</b>, more of them and harder to kill as the nights go on. They claw up out of open ground - roads and fields, never inside a house - and come at you from every side. Dawn comes only when the last wave falls.", "Four kinds make up the horde:", "<b>Risen Dead</b> - the most common. Fast, and quick with their claws. Wound one past half and it turns frenzied.", "<b>Shambling Maidens</b> - slower, tougher, their blows slow and heavy.", "<b>Grave Witches</b> - they hang back, hurl fire and call more Risen Dead out of the earth. Kill them first.", "<b>Volatiles</b> - bladed brutes, slow but the hardest hitters. Their hide turns half of every blow unless you strike the head or the back, and they leap at you from a distance.", "Some nights bring an elite Volatile, faster still, that comes through a portal and pounces. The Curse's champions and great ones step out of portals too - and their names burn gold over their heads." } },
		{ 0, "III. The Echo Altars", "wards", { "Long ago the <b>Tongues</b>, the first masters of the Voice, raised an altar in every hold to hold Alduin's shout back. Every mage who fell in the Dragon War gave a last spell to them, which is why an altar still has spells, bows and gifts to give.", "Alduin's return woke the altars only halfway. Each one is held silent by a <b>Dragon Priest</b>, still bound by his old oath to Alduin." } },
		{ 0, "IV. Waking an Altar", "", { "Stand at an altar and it sets you <b>trials</b>: hold its rune circle, cull the dead in its streets, hold the altar through a night's waves, and pass the trial of your own path. Finish them and its Dragon Priest rises at night. Kill him and the altar wakes.", "A woken altar makes its city a <b>sanctuary</b> - no dead rise inside it. If you have walked the <b>Way of the Voice</b> at High Hrothgar, its heart-stone also teaches you the city's own <b>shout</b>." } },
		{ 0, "V. The Dragonborn's Road", "", { "The Curse walks beside your own story; it does not replace it.", "<b>Riverwood's</b> altar, nearest Helgen, wakes first. <b>Whiterun's</b> answers your first dragon soul and gives you a dragon to ride. At <b>High Hrothgar</b>, the Way of the Voice opens the altars' shouts, and the <b>Reliquary</b> forges what the Dragon Priests leave behind into wonders.", "Win your path's <b>wonder</b> and Alduin's three Words wake, one at a time, at old places of the Dragon Cult. Silence <b>SLEN</b>, <b>TIID</b> and <b>VO</b> and the Curse is broken for good. And when you follow Alduin to Sovngarde and he falls, the mist thins and your wonder wakes to its <b>Legendary</b> form." } },
		{ 0, "VI. The Voices of the Holds", "", { "<b>Riverwood</b>: <i>Thunder Lash</i> (STRUN BAH QO). Lightning strikes the nearest dead - three, five or eight bolts, each leaping to one more.", "<b>Solitude</b>: <i>Raise the Fallen</i> (DIL VAAZ ZOL). The fallen rise to fight for you - two, four or six of them - and burst when their time is up.", "<b>Windhelm</b>: <i>Frost Nova</i> (IIZ SLEN NUS). A ring of frost freezes everything around you solid, and the frozen shatter when struck.", "<b>Markarth</b>: <i>Dwemer Quake</i> (GOL VAH DEN). The ground heaves in front of you and knocks the dead down - with the third word, stone spikes erupt through them.", "<b>Riften</b>: <i>Shadow Step</i> (FEIM ZII GRON). You blink forward through the horde, leaving a shadow that draws the dead to it and then bursts.", "<b>Falkreath</b>: <i>Death's Harvest</i> (KRII LUN AUS). A draining cone that heals you for every one of the dead it touches - the third word also raises a fallen friend nearby.", "<b>Morthal</b>: <i>Mire Grasp</i> (ZUN HAAL VIIK). Roots burst from the ground where you look, holding the dead in place and poisoning them.", "<b>Dawnstar</b>: <i>Nightmare Howl</i> (FAAS RU MAAR). The dead are thrown back in terror and slowed - and the weakest die of fright.", "<b>Winterhold</b>: <i>Arcane Singularity</i> (SU GRAH DUN). A vortex pulls the dead together where you look, then detonates.", "<b>Whiterun</b>: <i>Dragon's Updraft</i>. A whirlwind lifts you high - and a dragon to carry you." } },
		{ 0, "Epilogue", "", { "Every Echo Altar in Skyrim is awake. Alduin's voice lingers only in the wild places, and the mist will not lift from Sovngarde's door until the World-Eater falls.", "<i>- written in the silence of High Hrothgar</i>" } },
		{ 1, "The Summoner", "", { "A conjurer of the <b>College of Winterhold</b>. Your summons fight for you - every kill they make is yours: Cursed Essence, progress and trials.", "<b>You start with</b> Conjure Wolf (left hand), <b>Corrode Armor</b> (right hand) and Conjure Skeleton in your spellbook, and the summoner's robes. Corrosion is the Summoner's own element: its rust bolt bursts on impact, hurting and marking every enemy within 3 meters - your summons attack the marked enemies until they die or you mark new ones. Bind Pact at an Echo Altar climbs it to Armoreater and then Swordbreaker, each a wider, harder burst." } },
		{ 1, "Your Progress", "@progress", {  } },
		{ 1, "Your Altar", "", { "<b>Call a Summon</b> - the first rung of a summon family you don't have. You carry three of the altar's spells at a time - Corrosion and two summon families, or any three.", "<b>Bind a Hero</b> - your Legendary pact: a hero of old (Ysgramor, Miraak, the Ebony Warrior...) or a great army. Opens at <b>six freed altars</b>.", "The five families: <b>the Dead</b> (Skeleton to Death Overlord), <b>Beasts</b> (Wolf to Werebear), <b>Daedra</b> (Dremora to Warlock), <b>Dwemer</b> (Spider to Ballista Master) and <b>the Wild</b> (Spriggan to Earth Mother)." } },
		{ 1, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Kills by your summons (or your own, the spell in hand) count toward its next rung - <b>25</b>, then <b>60</b>, then <b>120</b> for the Legendary rung - once three Echo Altars are freed. Then hold it and take the altar's <b>Bind Pact</b> row: <b>5,000</b>, <b>8,000</b>, then <b>12,000</b> Cursed Essence, once a night per spell. A third rung waits for <b>four</b> freed altars, a Legendary for <b>six</b>. The Bind Pact row and <i>Your Progress</i> show the count.", "<b>Summon slots</b> - how many summons you can have out at the same time. You start with <b>2</b>, and get one more for every <b>2 Echo Altars</b> you free, up to <b>7</b> (<b>8</b> with the Conjurer's Command Mead). When every slot is full, a new summon replaces your oldest one." } },
		{ 1, "Your Perks", "", { "<b>Bonebinder's Brew</b> - your summons have 50% more health and deal 50% more damage.", "<b>Soul-Tether Wine</b> - each time one of your summons kills an enemy, you heal 5% of your maximum health.", "<b>Conjurer's Command Mead</b> - one more summon slot (up to 8).", "One of each perk a life - death takes them all." } },
		{ 1, "Your Trial and Wonder", "", { "<b>Pact of the Host</b> (your city trial): let your summons make the kills - 20 on Novice up to 60 on Legendary.", "<b>Horn of the Spectral Wyrm</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. Its last step hands you the wonder. It calls a spectral dragon for a minute - until it falls once Alduin is slain." } },
		{ 1, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> sprint at you and claw fast - hurt one past half and it turns frenzied; the <b>Shambling Maiden</b> is slower but tougher, and her blows come slow; the <b>Grave Witch</b> keeps back, hurls fire and calls more Risen Dead out of the ground - kill her first; the <b>Volatile</b>, a bladed brute, is slow but hits hardest and shrugs off half of every blow unless you hit its head or its back, and it leaps at you from a distance.", "Some nights bring a <b>Volatile</b>: an elite night-runner, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 1, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 Cursed Essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge / Bind Pact / Imbue</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 1, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 2, "The Battle-mage", "", { "A battle-mage of the <b>College of Winterhold</b>: a different element in each hand, struck from afar - bolts, beams, storms and runes.", "<b>You start with</b> Firebolt (right hand), Ice Spike (left hand), the Wild Witch's hat and gown and a Destruction tome." } },
		{ 2, "Your Progress", "@progress", {  } },
		{ 2, "Your Altar", "", { "<b>Call a Spell</b> - the first rung of an element you don't have. You carry two at a time.", "<b>Call a Support Spell</b> - Ash Cloud, Cinder Storm, Charged Nova or Symmetry, yours to keep.", "Six ladders, all cast from afar: <b>Fire</b>, <b>Frost</b>, <b>Shock</b>, <b>Sun</b>, <b>Blood</b> and <b>Runes</b>, four rungs each." } },
		{ 2, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Kills with the spell in your hand count toward its next rung - <b>25</b>, then <b>60</b>, then <b>120</b> for the Legendary rung - once three Echo Altars are freed. Then hold it and take the altar's <b>Reforge</b> row: <b>5,000</b>, <b>8,000</b>, then <b>12,000</b> Cursed Essence, once a night per spell. A third rung waits for <b>four</b> freed altars, a Legendary for <b>six</b>. The altar's Reforge row and <i>Your Progress</i> show the count." } },
		{ 2, "Your Perks", "", { "<b>Ember Heart Ale</b> - Destruction kills burst and hurt the dead nearby.", "<b>Arcanist's Focus Tea</b> - Destruction spells cost 25% less magicka.", "<b>Mana-Siphon Draught</b> - each Destruction kill gives back 6% magicka.", "One of each perk a life - death takes them all." } },
		{ 2, "Your Trial and Wonder", "", { "<b>Trial of the Elements</b> (your city trial): kill with two or more elements - 20 on Novice up to 60 on Legendary.", "<b>Tome of the Six Fires</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. Its last step hands you the wonder. One cast looses the top spell of all six elements around you." } },
		{ 2, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> sprint at you and claw fast - hurt one past half and it turns frenzied; the <b>Shambling Maiden</b> is slower but tougher, and her blows come slow; the <b>Grave Witch</b> keeps back, hurls fire and calls more Risen Dead out of the ground - kill her first; the <b>Volatile</b>, a bladed brute, is slow but hits hardest and shrugs off half of every blow unless you hit its head or its back, and it leaps at you from a distance.", "Some nights bring a <b>Volatile</b>: an elite night-runner, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 2, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 Cursed Essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge / Bind Pact / Imbue</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 2, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 3, "The Ranger", "", { "Sworn to the <b>Dawnguard</b>. Bows and crossbows - every arrow counts.", "<b>You start with</b> an elemental bow, the Dawnguard Crossbow with 30 bolts and the Drifter Outfit." } },
		{ 3, "Your Progress", "@progress", {  } },
		{ 3, "Your Altar", "", { "<b>Call a Bow or Crossbow</b> - one roll: six times in ten an elemental bow, four times in ten a crossbow or offhand bow. You carry one elemental bow; a new one takes its place.", "The bows: <b>Emberstring</b> (fire), <b>Rimehorn</b> (frost), <b>Stormreach</b> (shock), <b>Skyhowl</b> (wind), <b>Dawnspire</b> (sun), <b>Thirstbow</b> (blood). A full draw hits hardest.", "Better crossbows come as cities are freed (Dwarven and Elven at one, Glass and Ebony at two, Daedric and Dragonbone at three). <b>Q</b> / <b>R3</b> at the altar fills your quivers." } },
		{ 3, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Kills with a bow count toward its next tier - <b>25</b>, <b>60</b>, then <b>120</b> - once three Echo Altars are freed. Then hold it and take the altar's <b>Reforge</b> row: <b>5,000</b>, <b>8,000</b>, <b>12,000</b> Cursed Essence, once a night.", "Each tier: more damage, a new attack and a bigger quiver - <b>60</b>, <b>100</b>, <b>150</b>, <b>200</b> arrows - that regrows one arrow every <b>8</b>, <b>6</b>, <b>4</b>, then <b>2</b> seconds.", "<b>Crossbows</b>: kills unlock elemental bolts - fire at 25, ice at 60, shock at 120." } },
		{ 3, "Your Perks", "", { "<b>Fletcher's Sap Draught</b> - your arrows or bolts slowly grow back.", "<b>Eagle-Eye Draught</b> - bows draw and crossbows reload 25% faster.", "<b>Dawnwatch Tonic</b> - with a bow or crossbow out, the dead hurt you 25% less.", "One of each perk a life - death takes them all." } },
		{ 3, "Your Trial and Wonder", "", { "<b>Trial of the Long Shot</b> (your city trial): bow or crossbow kills from 30 m or more - 10 on Novice up to 30 on Legendary.", "<b>The Subsuming Vortex</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. Its last step hands you the wonder. Its arrows open black holes that drag the dead in, then burst - wider and stronger once Alduin is slain." } },
		{ 3, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> sprint at you and claw fast - hurt one past half and it turns frenzied; the <b>Shambling Maiden</b> is slower but tougher, and her blows come slow; the <b>Grave Witch</b> keeps back, hurls fire and calls more Risen Dead out of the ground - kill her first; the <b>Volatile</b>, a bladed brute, is slow but hits hardest and shrugs off half of every blow unless you hit its head or its back, and it leaps at you from a distance.", "Some nights bring a <b>Volatile</b>: an elite night-runner, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 3, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 Cursed Essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge / Bind Pact / Imbue</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 3, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 4, "The Spellsword", "", { "A <b>Vigilant of Stendarr</b>: steel in one hand, a touch spell in the other - fire, frost, shock, sun, blood or poison - that rides every blow of the blade.", "<b>You start with</b> the Steel Spellsword, a Steel Spellshield, Flame Touch (left hand) and the Practical Pirate outfit." } },
		{ 4, "Your Progress", "@progress", {  } },
		{ 4, "Your Altar", "", { "<b>Call a Spell</b> - the first rung of a touch you don't have: Fire, Frost, Shock, Sun, Blood or Poison. A <b>Legendary</b> touch on the blade earns <b>Twin Resonance</b>: your other touch rides it too, a quarter as strong. You carry two at a time.", "<b>Call a Spell-Weapon</b> - a one-handed spell-weapon, a spellshield, or a unique enchanted greatweapon (Trollsbane, Volendrung, the Ebony Blade...). One-handed spell-weapons hold one spell: whatever touch spell is in your other hand. Better steel comes as cities are freed." } },
		{ 4, "Getting Stronger", "", { "<b>Kills fill it, the altar raises it.</b> Melee kills with the spell in your other hand count toward its next rung - <b>25</b>, then <b>60</b>, <b>120</b> for a Legendary (a power-attack kill counts twice) - once three Echo Altars are freed. Then take the altar's <b>Imbue</b> row: <b>5,000</b> then <b>8,000</b> Cursed Essence (<b>12,000</b> for a Legendary), once a night. A third rung waits for <b>four</b> freed altars, a Legendary for <b>six</b>.", "Each reforge also raises your held spell-weapon a material and unlocks one of four <b>Enchantment Powers</b> (in your Powers)." } },
		{ 4, "Your Perks", "", { "<b>Bladesong Mead</b> - each melee hit heals you 2%.", "<b>Spellbinder's Draught</b> - melee kills give back 10% magicka.", "<b>Steel-Wind Ale</b> - melee swings 20% faster.", "One of each perk a life - death takes them all." } },
		{ 4, "Your Trial and Wonder", "", { "<b>Trial of Steel</b> (your city trial): melee kills with a spell in your other hand - 10 on Novice up to 30 on Legendary.", "<b>Dragon Slayer</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. Its last step hands you the wonder. Every hit carries your off-hand spell; once Alduin is slain, power attacks send it down the line." } },
		{ 4, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead come in four kinds: the <b>Risen Dead</b> sprint at you and claw fast - hurt one past half and it turns frenzied; the <b>Shambling Maiden</b> is slower but tougher, and her blows come slow; the <b>Grave Witch</b> keeps back, hurls fire and calls more Risen Dead out of the ground - kill her first; the <b>Volatile</b>, a bladed brute, is slow but hits hardest and shrugs off half of every blow unless you hit its head or its back, and it leaps at you from a distance.", "Some nights bring a <b>Volatile</b>: an elite night-runner, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Watch for tokens: skull (Insta-Kill), coin (Double Points), falling star (destroys tonight's corpses), chest (Fire Sale).", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 4, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for 2,500 Cursed Essence - each class keeps its own progress), <b>your rolls</b>, <b>Reforge / Bind Pact / Imbue</b> (after three freed altars), <b>perks</b>, then the city's <b>trials</b>.", "<b>After a roll</b>, activate the altar again: <b>take it</b> (it replaces what it would), <b>roll again</b> at the next price, or <b>leave it</b> for half the roll back.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. A freed city is a sanctuary, teaches you its Thu'um, and Whiterun gives you a dragon to ride." } },
		{ 4, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). From Novice to Legendary the dead have <b>0.6x, 0.8x, 1x, 1.6x, 2.2x, 3x</b> health and hit <b>0.5x to 2x</b> as hard. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 5, "The Broken Words: Riverwood", "", { "<i>We raised this altar in the valley where the river runs out of the mountains, and cut the valley's words into its heart-stone. Vahlok, the cult's jailor, watched us do it from the barrow on the peak. He swore to Alduin that no prisoner of his would ever go free - and the dead, to him, are prisoners.</i>", "The Dragon Priest of Riverwood: <b>Vahlok the Jailor</b>. Vahlok kept the cult's prisoners in the Merethic Era, and his oath to Alduin was the last he swore. It has brought him out of his tomb and across the sea to the barrow above Riverwood, to keep the valley's altar dark.", "The words on the heart-stone: <b>STRUN BAH QO</b> ('Storm Wrath Lightning') - <i>Thunder Lash</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 6, "The Broken Words: Whiterun", "", { "<i>The plains' altar is the one Nahkriin hates most, for it stands nearest the road to Sovngarde. He kept that road for Alduin at Skuldafn. When the World-Eater's mist lies on the door, Nahkriin will come to the plains to keep it there.</i>", "The Dragon Priest of Whiterun: <b>Nahkriin, Warden of Skuldafn</b>. Nahkriin guarded Skuldafn, the gate to Sovngarde, for Alduin, and the mist that bars Sovngarde's door is his to keep. He has come down from the mountains to the plains, so that Whiterun's dead never find the way home.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 7, "The Broken Words: Solitude", "", { "<i>Volsung could breathe on the peaks where we could not, and he laughed at our altar under the cliffs of Haafingar. But the Voice carries further than breath. The runes on its heart-stone hold the words that answer him.</i>", "The Dragon Priest of Solitude: <b>Volsung of Volskygge</b>. Volsung ruled the peaks above Haafingar from Volskygge, and his mask let him breathe where no man could. He climbs down to Solitude now, and the dead of the Blue Palace's crypts rise at his word.", "The words on the heart-stone: <b>DIL VAAZ ZOL</b> ('Undead Tear Zombie') - <i>Raise the Fallen</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 8, "The Broken Words: Windhelm", "", { "<i>Zahkriisos was not of this land; he came over the Sea of Ghosts with the cult's fleet, and the cold came with him. We set the altar of the east by the water so that it would hear him first if he ever came back across the ice.</i>", "The Dragon Priest of Windhelm: <b>Zahkriisos the Frost-Priest</b>. Zahkriisos lay in his tomb on Solstheim until Alduin's shout crossed the Sea of Ghosts. He walked over the ice to Windhelm's docks, and the cold he carries stops a heart.", "The words on the heart-stone: <b>IIZ SLEN NUS</b> ('Ice Flesh Statue') - <i>Frost Nova</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 9, "The Broken Words: Markarth", "", { "<i>Even the cult feared Otar. They walled him up in Ragnvald while he still breathed. We did not trust the wall, so we raised an altar on the Reach's stone and cut into it words he could not shout down.</i>", "The Dragon Priest of Markarth: <b>Otar the Mad</b>. Otar was so cruel that his own cult sealed him alive in Ragnvald. His oath to Alduin outlived his reason. He climbs out of the Reach's stone beneath Markarth to guard its altar.", "The words on the heart-stone: <b>GOL VAH DEN</b> ('Earth Spring Hold') - <i>Dwemer Quake</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 10, "The Broken Words: Riften", "", { "<i>Rahgot's people drank poison sooner than see him taken. A priest who can ask that of his followers will ask it again. When he rises, the Rift's dead will come with him, and the altar must be woken to send them back.</i>", "The Dragon Priest of Riften: <b>Rahgot of Forelhost</b>. Rahgot's followers poisoned themselves in Forelhost rather than surrender him to the Tongues. They rise with him now, and the Rift's dead follow them down to Riften's altar.", "The words on the heart-stone: <b>FEIM ZII GRON</b> ('Fade Spirit Bind') - <i>Shadow Step</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 11, "The Broken Words: Falkreath", "", { "<i>Krosis wept for a thousand years at Shearpoint, guarding a word no one came to learn. Grief is a long oath. The altar of the pines is cut with gentler words than the rest - to put children back to sleep.</i>", "The Dragon Priest of Falkreath: <b>Krosis of Shearpoint</b>. Krosis guarded the word at Shearpoint, mourning, for a thousand years. Alduin's shout gave him something to do with his sorrow: he comes down to Falkreath's graveyard to keep its children in the ground no longer.", "The words on the heart-stone: <b>KRII LUN AUS</b> ('Kill Leech Suffer') - <i>Death's Harvest</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 12, "The Broken Words: Morthal", "", { "<i>Hevnoraak's own servants sealed him in Valthume, and set the seal with his blood. No seal holds against SLEN TIID VO. When the marsh fog thickens, look to the altar, and to the words on its heart-stone.</i>", "The Dragon Priest of Morthal: <b>Hevnoraak of Valthume</b>. Hevnoraak's servants sealed him in Valthume to stop him rising. The seal could not hold against SLEN TIID VO: he walks out of the marsh fog, and Hjaalmarch's drowned dead follow him.", "The words on the heart-stone: <b>ZUN HAAL VIIK</b> ('Weapon Hand Defeat') - <i>Mire Grasp</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 13, "The Broken Words: Dawnstar", "", { "<i>Vokun's shadows reached into men's dreams. The priests at the temple on the hill dreamed of him for a thousand years before he came. Wake the altar, and the town will sleep without dreaming of him again.</i>", "The Dragon Priest of Dawnstar: <b>Vokun of High Gate</b>. Vokun was a priest of shadows, and the Nightcaller's dreamers in Dawnstar dreamed his return a thousand years before it came. Kill him, and Dawnstar's nightmares end.", "The words on the heart-stone: <b>FAAS RU MAAR</b> ('Fear Run Terror') - <i>Nightmare Howl</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 14, "The Broken Words: Winterhold", "", { "<i>Morokei held the Staff of Magnus in Bromjunaar, and the mages who came after us have never forgotten him. The northern altar stands on the cliffs where the storms break; its words are cut deepest of all, for he is the strongest of them.</i>", "The Dragon Priest of Winterhold: <b>Morokei of Labyrinthian</b>. Morokei once held the Staff of Magnus in Labyrinthian, and the College has feared him ever since. He has come to the cliffs above Winterhold, and the storm he calls has not finished yet.", "The words on the heart-stone: <b>SU GRAH DUN</b> ('Air Battle Grace') - <i>Arcane Singularity</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
	};
}
